function main(): void {
  const r: any = new ReadableStream();
  const w: any = new WritableStream();
  const t: any = new TransformStream();
  const e: any = new TextEncoderStream();
  const d: any = new TextDecoderStream();
  const c: any = new CompressionStream('gzip');
  console.log(Object.keys(r).length, Object.keys(w).length, Object.keys(t).length, Object.keys(e).length, Object.keys(d).length, Object.keys(c).length);
  console.log(JSON.stringify(r), JSON.stringify(t), r.locked, w.locked, typeof t.readable, typeof e.writable);
}
